INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Komponentendiagramm nur für komplexe Systeme relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Systeme profitieren von Übersicht"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Komponentendiagramm?', 3, '[{"text": "Systemarchitektur zeigen", "correct": true, "because": "Visualisiert Modulaufteilung"}, {"text": "Datenfluss definieren", "correct": false, "because": "Datenflussdiagramm-Thema"}, {"text": "Code implementieren", "correct": false, "because": "Kein Programmierfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Komponentendiagramm?', 5, '[{"text": "Komponenten", "correct": true, "because": "Repräsentieren Module"}, {"text": "Schnittstellen", "correct": true, "because": "Zeigen Interaktionen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Diagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Komponentendiagramme zeigen Module. b) Sie ersetzen Klassendiagramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klassendiagramme sind detaillierter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Komponentendiagramm?', 4, '[{"text": "Komponenten", "correct": false, "because": "Kern des Diagramms"}, {"text": "Schnittstellen", "correct": false, "because": "Zeigen Verbindungen"}, {"text": "Code-Details", "correct": true, "because": "Abstrakte Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Komponentendiagramm auch Hardware zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Softwaremodule"}, {"text": "Ja", "correct": false, "because": "Verteilungsdiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für ein Komponentendiagramm?', 3, '[{"text": "Komponente", "correct": true, "because": "Repräsentiert Modul"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Klassenmethoden", "correct": false, "because": "Klassendiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen zeigt ein Komponentendiagramm?', 5, '[{"text": "Modulaufteilung", "correct": true, "because": "Zeigt Softwarestruktur"}, {"text": "Schnittstellen", "correct": true, "because": "Interaktionen sichtbar"}, {"text": "Hardwareknoten", "correct": false, "because": "Verteilungsdiagramm"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Diagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Komponentendiagramme sind für Architektur wichtig. b) Sie zeigen Laufzeitinstanzen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Instanzen sind Objektdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Komponentendiagramm?', 4, '[{"text": "Komponenten", "correct": false, "because": "Kern des Diagramms"}, {"text": "Schnittstellen", "correct": false, "because": "Zeigen Interaktionen"}, {"text": "Methodenaufrufe", "correct": true, "because": "Detail für Klassendiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Komponentendiagramm auch Hardware?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Software"}, {"text": "Ja", "correct": false, "because": "Verteilungsdiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen nutze ich in einem Komponentendiagramm?', 4, '[{"text": "Abhängigkeiten", "correct": true, "because": "Zeigen Verbindungen"}, {"text": "Schnittstellenverbindungen", "correct": true, "because": "Definieren Interaktionen"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Komponentendiagramme nur für Entwickler sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Architekten"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Komponentendiagramm?', 3, '[{"text": "Klarheit der Module", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Zeichnung", "correct": false, "because": "Qualität zählt"}, {"text": "Code-Details", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Komponentendiagramme sind Teil von UML. b) Sie zeigen Hardwarezuordnung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Komponentendiagramm?', 5, '[{"text": "Modulübersicht", "correct": true, "because": "Klarheit über Struktur"}, {"text": "Interaktionsplanung", "correct": true, "because": "Schnittstellen sichtbar"}, {"text": "Datenflussanalyse", "correct": false, "because": "Anderes Diagramm"}, {"text": "Hardwareplanung", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Komponentendiagramm unwichtig?', 3, '[{"text": "Komponenten", "correct": false, "because": "Kern der Darstellung"}, {"text": "Abhängigkeiten", "correct": false, "because": "Zeigen Beziehungen"}, {"text": "UI-Design", "correct": true, "because": "Kein Architekturaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Komponentendiagramm auch Abläufe?', 3, '[{"text": "Nein", "correct": true, "because": "Statisch, nicht dynamisch"}, {"text": "Ja", "correct": false, "because": "Abläufe in Sequenzdiagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Komponentendiagramm für kleine Module übertrieben ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme strukturierbar"}, {"text": "Ja", "correct": false, "because": "Skalierung unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Komponente?', 4, '[{"text": "Rechteck mit Zahnrad", "correct": true, "because": "UML-Standard für Komponenten"}, {"text": "Pfeil", "correct": false, "because": "Nur Verbindung"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}]');
